={{ (() => {
  const budget = String($('Prepare Lead Data').item.json.budget || '')
    .replace(/\s/g, '')
    .replace(/[–—]/g, '-');

  const timeline = String($('Prepare Lead Data').item.json.timeline || '')
    .replace(/[–—]/g, '-')
    .trim();

  const budgetPoints = {
    '20M+': 50,
    '10M-20M': 40,
    '5M-10M': 25,
    'Under5M': 10,
    'NotSure': 0
  }[budget] ?? 0;

  const timelinePoints = {
    'Immediately': 50,
    'Within 1 Month': 40,
    '1-3 Months': 25,
    '3-6 Months': 10,
    'Just Exploring': 0
  }[timeline] ?? 0;

  return budgetPoints + timelinePoints;
})() }}

={{ (() => {
  const budget = String($('Prepare Lead Data').item.json.budget || '')
    .replace(/\s/g, '')
    .replace(/[–—]/g, '-');

  const timeline = String($('Prepare Lead Data').item.json.timeline || '')
    .replace(/[–—]/g, '-')
    .trim();

  const budgetPoints = {
    '20M+': 50,
    '10M-20M': 40,
    '5M-10M': 25,
    'Under5M': 10,
    'NotSure': 0
  }[budget] ?? 0;

  const timelinePoints = {
    'Immediately': 50,
    'Within 1 Month': 40,
    '1-3 Months': 25,
    '3-6 Months': 10,
    'Just Exploring': 0
  }[timeline] ?? 0;

  const score = budgetPoints + timelinePoints;

  return score >= 80 ? 'Hot' : score >= 40 ? 'Warm' : 'Normal';
})() }}

={{ (() => {
  const priority = $json.lead_priority || '';
  const service = String($json.service || '').toLowerCase();

  if (priority === 'Hot') return $json.senior_agent_email;
  if (service.includes('construction')) return $json.construction_agent_email;

  return $json.general_sales_email;
})() }}
